# Рабочая тетрадь проекта и данные кейса в .xlsx: python3 tools/build-xlsx.py
import csv
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill, Alignment
from openpyxl.utils import get_column_letter
H=Font(bold=True); FILL=PatternFill('solid',fgColor='D6ED8C'); IN=PatternFill('solid',fgColor='DCEBFA'); WR=Alignment(wrap_text=True,vertical='top')
wb=Workbook()
def sheet(title,note,headers,rows=(),widths=None,first=False,wbk=None):
    w=wbk or wb
    ws=w.active if first else w.create_sheet()
    ws.title=title
    ws['A1']=note; ws['A1'].alignment=WR; ws.merge_cells(start_row=1,start_column=1,end_row=1,end_column=max(len(headers),4)); ws.row_dimensions[1].height=95
    for i,h in enumerate(headers,1):
        c=ws.cell(row=3,column=i,value=h); c.font=H; c.fill=FILL; c.alignment=WR
        ws.column_dimensions[get_column_letter(i)].width=(widths[i-1] if widths else 18)
    for r,row in enumerate(rows,4):
        for i,v in enumerate(row,1): ws.cell(row=r,column=i,value=v).alignment=WR
    ws.freeze_panes='A4'
    return ws
