ws.cell(row=36,column=3,value='Доля совпадений:').font=H; ws.cell(row=36,column=4,value='=IFERROR(AVERAGE(D15:D34),"")')
sheet('КТ-1 Тайный покупатель','Сценарий запроса одинаков для всех объектов (подробно — в памятке «Тайный покупатель»): даты заезда, состав гостей, вопрос «какая итоговая сумма к оплате и какие условия отмены?». По возможности разные каналы: телефон, мессенджер, форма на сайте. Не бронируйте и не отменяйте реальные заказы.',
 ['Объект','Канал','Дата и время запроса','Время ответа, мин','Итоговая цена, ₽','Обязательные платежи сверх тарифа','Условия отмены','Предложили альтернативу?','Полнота ответа (0–2)','Заметки'],
 [['','','','','','','','','',''] for _ in range(3)],[22,16,18,14,14,22,26,16,14,30])
ws=sheet('КТ-3 Цены по датам','Минимум: 3 объекта × 2 даты заезда (пик и межсезонье) × 2 канала (сайт объекта и площадка бронирования) = 12 замеров в один день съёма. Горизонты бронирования и больше объектов — по желанию. Итоговая цена считается автоматически.',
 ['Дата съёма','Объект','Дата заезда','Тип даты','Дней до заезда','Канал','Тариф, ₽','Обязательные платежи, ₽','Итоговая цена, ₽','Условия отмены'],[],[12,22,12,14,12,18,12,16,14,30])
for r in range(4,16): ws.cell(row=r,column=9,value=f'=IF(G{r}="","",G{r}+N(H{r}))')
ws=sheet('КТ-4 Модель','Модель альтернатив на примере «Маяка». Голубые ячейки — входные данные: замените их числами своего объекта в столбце «Ваш вариант». Если объект не гостиница: номеро-ночь → место в группе или вход на тропу в день; агрегатор → посредник с комиссией; вытеснение → заявки сверх допустимой нагрузки или вытесненные более выгодные группы.',
 ['Показатель','Агрегатор','Прямой','Корпоративный','Ваш вариант','Пояснение'],[],[40,16,16,16,16,50])
rows=[('Забронировано, ед.',[375,300,320],'Номеро-ночи до отмен'),('Доля отмен',[0.2,0.2,0.0625],'Доля забронированных единиц'),
('Состоялось, ед.','{c}4*(1-{c}5)','Формула'),('Цена состоявшейся единицы, ₽',[6000,6200,5400],''),
('Комиссия или обработка, доля выручки',[0.18,0.02,0],''),('Доп. обработка на состоявшуюся единицу, ₽',[0,0,100],''),
('Обслуживание состоявшейся единицы, ₽',[1800,1800,1800],'Переменные затраты'),('Привлечение на забронированную единицу, ₽',[0,600,0],'Не возвращается при отмене'),
('Фиксированный расход пакета, ₽',[30000,90000,40000],''),('Результат до вытеснения, ₽','{c}6*({c}7*(1-{c}8)-{c}9-{c}10)-{c}4*{c}11-{c}12','Формула'),
('Единиц пакета в пик',[120,40,180],'Распределение состоявшихся по периодам'),('Мощность пика',[400,400,400],'10 дней × 40 номеров'),
('Базовый спрос пика',[370,370,370],'Подтверждённый + ожидаемый'),('Вытеснено в пик, ед.','MAX(0,MIN({c}14,{c}16+{c}14-{c}15))','Формула'),
('Маржинальный доход вытесненной единицы, ₽',[5060,5060,5060],'7 000 × 0,98 − 1 800'),('Результат после вытеснения, ₽','{c}13-{c}17*{c}18','Формула')]
for i,(label,vals,expl) in enumerate(rows,4):
    ws.cell(row=i,column=1,value=label); ws.cell(row=i,column=6,value=expl)
    for j,col in enumerate('BCDE'):
        if isinstance(vals,str): ws[f'{col}{i}']='='+vals.format(c=col)
        else:
            if j<3: ws[f'{col}{i}']=vals[j]
            ws[f'{col}{i}'].fill=IN
ws['A21']='Порог: при каком маржинальном доходе вытесненной единицы меняется выбор? Меняйте ячейки строки 18 и смотрите строку 19.'
# Данные кейса
case=list(csv.reader(open('data/case.csv',encoding='utf-8')))
names={'channel':'Канал','booked_room_nights':'Забронировано номеро-ночей','cancellation_rate':'Доля отмен','expected_stayed_room_nights':'Ожидаемо состоится','price_rub':'Цена ночи, ₽','revenue_fee_rate':'Комиссия/обработка, доля выручки','fee_per_stayed_night_rub':'Обработка на ночь, ₽','service_cost_per_stayed_night_rub':'Обслуживание ночи, ₽','acquisition_cost_per_booked_night_rub':'Привлечение на бронь, ₽','package_fixed_cost_rub':'Фиксированный расход пакета, ₽','peak_stayed_nights':'Ночей в пик','offpeak_stayed_nights':'Ночей вне пика'}
chan={'aggregator':'Агрегатор','direct':'Прямой','corporate':'Корпоративный'}
def num(v):
    try: return int(v)
    except ValueError:
        try: return float(v)
        except ValueError: return chan.get(v,v)
note='Данные кейса «Маяк»: три дополнительных пакета продаж на расчётный месяц (40 номеров × 30 дней = 1 200 номеро-ночей). Денежные суммы в рублях, доли — от 0 до 1.'
cw=Workbook(); sheet('Данные кейса',note,[names[h] for h in case[0]],[[num(v) for v in r] for r in case[1:]],[14]+[16]*11,first=True,wbk=cw)
cw.save('data/case.xlsx')
sheet('Данные кейса',note,[names[h] for h in case[0]],[[num(v) for v in r] for r in case[1:]],[14]+[16]*11)
wb.save('data/project-templates.xlsx'); print('xlsx ok')
